import{_ as s,o as a,c as t,ae as i}from"./chunks/framework.Co1PSFSm.js";const u=JSON.parse('{"title":"","description":"Troubleshooting Fresh applications.\\n","frontmatter":{"description":"Troubleshooting Fresh applications.\\n"},"headers":[],"relativePath":"en/latest/latest/advanced/troubleshooting.md","filePath":"en/latest/latest/advanced/troubleshooting.md"}'),n={name:"en/latest/latest/advanced/troubleshooting.md"};function o(r,e,l,h,d,p){return a(),t("div",null,[...e[0]||(e[0]=[i(`<p>This site contains some tips to troubleshoot your app in case something doesn&#39;t work as expected.</p><h2 id="update-deno" tabindex="-1">Update Deno <a class="header-anchor" href="#update-deno" aria-label="Permalink to &quot;Update Deno&quot;">​</a></h2><p>The Node compatibility layer in Deno is constantly receiving new improvements and bug fixes with every Deno version. Chances are that the issue you&#39;re running into has already been fixed. To rule that out, install the latest Deno version.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">deno</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> upgrade</span></span></code></pre></div><h2 id="install-or-re-install-dependencies" tabindex="-1">Install or re-install dependencies <a class="header-anchor" href="#install-or-re-install-dependencies" aria-label="Permalink to &quot;Install or re-install dependencies&quot;">​</a></h2><p>When run for the first time, you might see Deno complaining about missing packages. Install them with:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">deno</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --allow-scripts</span></span></code></pre></div><p>If you run into dependency trouble later and suspect that Deno might be caching an outdated package, you can force a clean reinstall by adding <code>-r</code> to the above command.</p><h2 id="update-fresh" tabindex="-1">Update Fresh <a class="header-anchor" href="#update-fresh" aria-label="Permalink to &quot;Update Fresh&quot;">​</a></h2><p>The easiest way to resolve most issues is to ensure that you&#39;re on the <a href="https://jsr.io/@fresh/core/versions" target="_blank" rel="noreferrer">latest version</a> of Fresh. We continuously work on Fresh and there is a good chance that the issue you&#39;re running into has already been resolved in the latest version of Fresh.</p><h2 id="don-t-use-esm-sh" tabindex="-1">Don&#39;t use esm.sh <a class="header-anchor" href="#don-t-use-esm-sh" aria-label="Permalink to &quot;Don&#39;t use esm.sh&quot;">​</a></h2><p>Fresh 1.x heavily relied on <a href="https://esm.sh/" target="_blank" rel="noreferrer">esm.sh</a> to be able to use npm packages with Fresh. This continued a bit through the early alpha versions of Fresh 2. With the move to <a href="/docs/advanced/vite.html"><code>vite</code></a> this is not necessary anymore and you should use the relevant npm package directly from npm.</p><div class="language-diff vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">diff</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    &quot;imports&quot;: {</span></span>
<span class="line"><span style="--shiki-light:#B31D28;--shiki-dark:#FDAEB7;">-     &quot;cowsay&quot;: &quot;https://esm.sh/cowsay&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">+     &quot;cowsay&quot;: &quot;npm:cowsay@^1.6.0&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span></code></pre></div><blockquote><p>[info]: Not using <code>esm.sh</code> solves many issues and footguns with duplicate Preact versions in your app. If you&#39;re seeing strange JavaScript errors in the browser in your app then this is likely the cause.</p></blockquote><h2 id="attach-a-debugger" tabindex="-1">Attach a debugger <a class="header-anchor" href="#attach-a-debugger" aria-label="Permalink to &quot;Attach a debugger&quot;">​</a></h2><p>To attach a debugger to vite with Deno run this command:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">deno</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -A</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --inspect</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> npm:vite</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># or</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">deno</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -A</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --inspect-brk</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> npm:vite</span></span></code></pre></div><h2 id="debug-vite-resolution" tabindex="-1">Debug vite resolution <a class="header-anchor" href="#debug-vite-resolution" aria-label="Permalink to &quot;Debug vite resolution&quot;">​</a></h2><p>To debug vite resolution issues run vite with the <code>--debug</code> flag. This will print lots of debugging information to the terminal.</p><h2 id="debug-vite-transformations" tabindex="-1">Debug vite transformations <a class="header-anchor" href="#debug-vite-transformations" aria-label="Permalink to &quot;Debug vite transformations&quot;">​</a></h2><p>To debug vite plugin transformations, use <a href="https://github.com/antfu-collective/vite-plugin-inspect" target="_blank" rel="noreferrer"><code>vite-plugin-inspect</code></a>. This gives you a UI that shows all transformations of all plugins for every file.</p><h2 id="my-deployment-won-t-start" tabindex="-1">My deployment won&#39;t start <a class="header-anchor" href="#my-deployment-won-t-start" aria-label="Permalink to &quot;My deployment won&#39;t start&quot;">​</a></h2><p>If your deployment doesn&#39;t boot, check the following things:</p><ol><li>Make sure that you ran <code>deno task build</code>.</li><li>Make sure that your entry points to the generated <code>_fresh/server.js</code> file instead of <code>main.ts</code>. The latter won&#39;t work with Fresh 2.</li></ol><p>Error messages like <code>ISOLATE_INTERNAL_FAILURE</code> may indicate above issues, but can also be caused by other problems in your deployment configuration.</p><h2 id="vs-code-does-not-find-packages-and-or-types" tabindex="-1">VS Code does not find packages and/or types <a class="header-anchor" href="#vs-code-does-not-find-packages-and-or-types" aria-label="Permalink to &quot;VS Code does not find packages and/or types&quot;">​</a></h2><p>If you see errors in VS Code like <code>Cannot find module &#39;fresh/runtime&#39;</code> or see a lot of TypeScript errors, you likely have not installed the Deno extension. You can easily find it inside VS Code&#39;s extension browser (identifier: <code>denoland.vscode-deno</code>).</p><p>Once installed and enabled, the currently installed Deno version should appear in the bottom status bar. If this does not happen automatically, you can enable the Deno extension via the command palette (Cmd+Shift+P on macOS, Ctrl+Shift+P on Windows/Linux) and run <code>Deno: Enable</code>.</p><p>For detailed instructions, see the official <a href="https://docs.deno.com/runtime/reference/vscode/" target="_blank" rel="noreferrer">Deno VS Code documentation</a>.</p>`,29)])])}const g=s(n,[["render",o]]);export{u as __pageData,g as default};
